      tactics: { J: ['Judging', 'ชอบวางแผน', 'You like plans and order.', 'คุณชอบแผนการและความเป็นระเบียบ'], P: ['Prospecting', 'ยืดหยุ่น', 'You like freedom and surprises.', 'คุณชอบอิสระและเรื่องที่ไม่คาดคิด'] },
